34	// TestGetTranslationDictConcurrency exercises the lazy population of the
35	// catalog from concurrent goroutines, as HTTP request handlers do. It must be
36	// run with the race detector enabled to catch unsynchronized catalog access.
37	func TestGetTranslationDictConcurrency(t *testing.T) {
38		defaultCatalog = make(catalog, len(AvailableLanguages))
39	
40		const iterations = 10
41	
42		var wg sync.WaitGroup
43		for i := 0; i < iterations; i++ {
44			for language := range AvailableLanguages {
45				wg.Add(1)
46				go func(language string) {
47					defer wg.Done()
48	
49					dict, err := getTranslationDict(language)
50					if err != nil {
51						t.Errorf(`Unable to get translation dictionary for language %q: %v`, language, err)
52						return
53					}
54					if len(dict.singulars) == 0 {
55						t.Errorf(`The translation dictionary for language %q should not be empty`, language)
56					}
57				}(language)
58			}
59		}
60		wg.Wait()
61	}
62	
63	func TestLoadCatalog(t *testing.T) {
64		for language := range AvailableLanguages {
65			_, err := loadTranslationFile(language)
66			if err != nil {
67				t.Fatal(err)
68			}
69		}
70	}
