72	func TestAllKeysHaveValue(t *testing.T) {
73		for language := range AvailableLanguages {
74			messages, err := loadTranslationFile(language)
75			if err != nil {
76				t.Fatalf(`Unable to load translation messages for language %q`, language)
77			}
78	
79			if len(messages.singulars) == 0 {
80				t.Fatalf(`The language %q doesn't have any messages for singulars`, language)
81			}
82	
83			if len(messages.plurals) == 0 {
84				t.Fatalf(`The language %q doesn't have any messages for plurals`, language)
85			}
86	
87			for k, v := range messages.singulars {
88				if len(v) == 0 {
89					t.Errorf(`The key %q for singulars for the language %q has an empty list as value`, k, language)
90				}
91			}
92			for k, v := range messages.plurals {
93				if len(v) == 0 {
94					t.Errorf(`The key %q for plurals for the language %q has an empty list as value`, k, language)
95				}
96			}
97		}
98	}
99	
100	func TestMissingTranslations(t *testing.T) {
101		refLang := "en_US"
102		references, err := loadTranslationFile(refLang)
103		if err != nil {
104			t.Fatal(`Unable to parse reference language`)
105		}
106	
107		for language := range AvailableLanguages {
108			if language == refLang {
109				continue
110			}
111	
112			messages, err := loadTranslationFile(language)
113			if err != nil {
114				t.Fatalf(`Parsing error for language %q`, language)
115			}
116	
117			for key := range references.singulars {
118				if _, found := messages.singulars[key]; !found {
119					t.Errorf(`Translation key %q not found in language %q singulars`, key, language)
120				}
121			}
122			for key := range references.plurals {
123				if _, found := messages.plurals[key]; !found {
124					t.Errorf(`Translation key %q not found in language %q plurals`, key, language)
125				}
126			}
127		}
128	}
