144			"ko_KR":            1,
145			"nan_Latn_pehoeji": 1,
146			"nl_NL":            2,
147			"pl_PL":            3,
148			"pt_BR":            2,
149			"ro_RO":            3,
150			"ru_RU":            3,
151			"tr_TR":            2,
152			"uk_UA":            3,
153			"vi_VN":            1,
154			"zh_CN":            1,
155			"zh_TW":            1,
156		}
157		for language := range AvailableLanguages {
158			messages, err := loadTranslationFile(language)
159			if err != nil {
160				t.Fatalf(`Unable to load translation messages for language %q`, language)
161			}
162	
163			for k, v := range messages.plurals {
